from collections import deque

graph = {1: [2, 3], 2: [1, 4], 3: [1, 4], 4: [2, 3, 5], 5: [4]}
dist = {1: 0}
queue = deque([1])
order = []
while queue:
    node = queue.popleft()
    order.append(node)
    for nxt in graph[node]:
        if nxt not in dist:
            dist[nxt] = dist[node] + 1
            queue.append(nxt)
print(order)  # [1, 2, 3, 4, 5]
print(dist)   # {1: 0, 2: 1, 3: 1, 4: 2, 5: 3}
